// JCSParityFixtureTests is the cross-language byte-parity anchor for
// the Swift JCSCanonicalizer + ContentHasher. It reads the shared
// fixture at `backend/internal/service/testdata/external_contact_hash_parity.json`
// (generated by `backend/cmd/dump-external-contact-hash-fixture`) and
// asserts that the Swift canonicalizer reproduces the documented
// canonical bytes AND that ContentHasher reproduces the SHA-256 hex
// (for entries with `strip_host=true`).
//
// The same file is consumed by the Go-side
// `TestExternalContactHash_ParityFixture` — drift on either side
// fails loudly.
//
// Path resolution uses `#filePath` (NOT `#file`) per Swift 6 / SE-0274
// so we can walk up to the repo root and find the shared fixture.
import XCTest
@testable import CRMMacCore

final class JCSParityFixtureTests: XCTestCase {

    private struct FixtureFile: Decodable {
        struct Entry: Decodable {
            let name: String
            let note: String?
            let input: AnyJSON
            let stripHost: Bool
            let canonical: String
            let sha256: String

            enum CodingKeys: String, CodingKey {
                case name, note, input
                case stripHost = "strip_host"
                case canonical, sha256
            }
        }
        let entries: [Entry]
    }

    func testParityFixture() throws {
        let url = Self.resolveFixtureURL()
        guard FileManager.default.fileExists(atPath: url.path) else {
            XCTFail("parity fixture missing at \(url.path); regenerate via "
                    + "`go run ./backend/cmd/dump-external-contact-hash-fixture > "
                    + "backend/internal/service/testdata/external_contact_hash_parity.json`")
            return
        }
        let data = try Data(contentsOf: url)
        let file = try JSONDecoder().decode(FixtureFile.self, from: data)
        XCTAssertFalse(file.entries.isEmpty, "fixture must contain entries")

        for entry in file.entries {
            try runEntry(entry)
        }
    }

    private func runEntry(_ entry: FixtureFile.Entry) throws {
        // Re-serialize the parsed `input` back to compact JSON bytes
        // (matching the Go-side dump helper, which writes via
        // json.Marshal of the same parsed shape).
        let inputBytes = try compactSerialize(entry.input)
        var workingBytes = inputBytes
        if entry.stripHost {
            workingBytes = try stripHostID(workingBytes)
        }
        let canonical = try JCSCanonicalizer.canonicalize(workingBytes)
        guard let canonicalString = String(data: canonical, encoding: .utf8) else {
            XCTFail("entry=\(entry.name): canonical output not UTF-8")
            return
        }
        XCTAssertEqual(canonicalString, entry.canonical,
                       "canonical drift on entry=\(entry.name)")

        // Hash check for the strip_host=true entries also goes through
        // ContentHasher to confirm the wrapper agrees end-to-end.
        if entry.stripHost {
            let hash = try ContentHasher.contentHash(for: inputBytes)
            XCTAssertEqual(hash, entry.sha256,
                           "sha256 drift on entry=\(entry.name)")
        }
    }

    /// Strip the top-level `host_id` key from a JSON object's bytes.
    /// Used to mirror `sjson.DeleteBytes(payload, "host_id")` on the
    /// Go side. This Swift-side helper parses + re-serializes via
    /// JSONSerialization which collapses semantically-equivalent
    /// representations — fine because the canonicalizer itself is the
    /// byte-level invariant we care about.
    private func stripHostID(_ bytes: Data) throws -> Data {
        let parsed = try JSONSerialization.jsonObject(with: bytes, options: [])
        guard var obj = parsed as? [String: Any] else {
            return bytes
        }
        obj.removeValue(forKey: "host_id")
        return try JSONSerialization.data(withJSONObject: obj, options: [])
    }

    /// Re-serialize an AnyJSON tree to compact UTF-8 bytes (no
    /// whitespace, no escaped slashes). Mirrors the Go-side
    /// `json.Marshal` behavior the dump helper relies on.
    private func compactSerialize(_ v: AnyJSON) throws -> Data {
        try JSONSerialization.data(
            withJSONObject: v.unwrapped,
            options: [])
    }

    private static func resolveFixtureURL() -> URL {
        // .../mac-daemon/Tests/CRMMacCoreTests/JCSParityFixtureTests.swift
        //   -> .../CRMMacCoreTests/
        //   -> .../Tests/
        //   -> .../mac-daemon/
        //   -> .../<repo-root>/
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .appendingPathComponent(
                "backend/internal/service/testdata/external_contact_hash_parity.json")
    }
}

// MARK: - AnyJSON

/// AnyJSON is a thin Decodable wrapper that captures arbitrary JSON
/// values so the test can re-serialize them into compact bytes the
/// canonicalizer can ingest. Mirrors the `interface{}`-style
/// behavior of Go's `json.RawMessage` decode + re-marshal cycle.
enum AnyJSON: Decodable {
    case null
    case bool(Bool)
    case number(NSNumber)
    case string(String)
    case array([AnyJSON])
    case object([String: AnyJSON])

    init(from decoder: Decoder) throws {
        let c = try decoder.singleValueContainer()
        if c.decodeNil() { self = .null; return }
        if let b = try? c.decode(Bool.self) { self = .bool(b); return }
        if let i = try? c.decode(Int64.self) {
            self = .number(NSNumber(value: i))
            return
        }
        if let d = try? c.decode(Double.self) {
            self = .number(NSNumber(value: d))
            return
        }
        if let s = try? c.decode(String.self) { self = .string(s); return }
        if let a = try? c.decode([AnyJSON].self) { self = .array(a); return }
        if let o = try? c.decode([String: AnyJSON].self) { self = .object(o); return }
        throw DecodingError.dataCorruptedError(
            in: c, debugDescription: "AnyJSON: unsupported value")
    }

    /// Re-unwrap into the Foundation tree JSONSerialization expects.
    var unwrapped: Any {
        switch self {
        case .null: return NSNull()
        case .bool(let b): return b
        case .number(let n): return n
        case .string(let s): return s
        case .array(let a): return a.map { $0.unwrapped }
        case .object(let o):
            var out: [String: Any] = [:]
            for (k, v) in o { out[k] = v.unwrapped }
            return out
        }
    }
}
